inline void rollbackUpdate(const fs::path& root){auto journal=json::parse(readFile(updatePath(root,L".updates/pending.json")));auto old=str(journal,"old_sha256"),newHash=str(journal,"new_sha256");if(!std::regex_match(old,std::regex("[0-9a-f]{64}"))||!std::regex_match(newHash,std::regex("[0-9a-f]{64}")))throw std::runtime_error("복구 기록 오류");auto target=updatePath(root,L"SNUWCANVAS.exe"),backup=updatePath(root,L".updates/backups/"+wide(old)+L".exe"),restore=updatePath(root,L".updates/restore.exe"),failed=updatePath(root,L".updates/failed/"+wide(newHash)+L".exe");if(!fs::exists(backup)||fileSha256(backup)!=old)throw std::runtime_error("이전 버전 백업 검증 실패");if(fs::exists(target)&&fileSha256(target)==old){journal["state"]="rolled_back";updateJournal(root,journal);return;}if(fs::exists(target)&&fileSha256(target)!=newHash)throw std::runtime_error("대상 EXE가 변경되어 자동 복구를 중단했습니다.");fs::create_directories(failed.parent_path());fs::copy_file(backup,restore,fs::copy_options::overwrite_existing);durableFile(restore);if(fs::exists(target)){if(fs::exists(failed))fs::remove(failed);if(!ReplaceFileW(target.c_str(),restore.c_str(),failed.c_str(),0,nullptr,nullptr))throw std::runtime_error("이전 EXE 복구 실패");}else if(!MoveFileExW(restore.c_str(),target.c_str(),MOVEFILE_WRITE_THROUGH))throw std::runtime_error("EXE 복구 실패");journal["state"]="rolled_back";updateJournal(root,journal);}
inline std::wstring updateQuote(const std::wstring& value){std::wstring out=L"\"";size_t slash=0;for(wchar_t c:value){if(c==L'\\'){slash++;continue;}if(c==L'\"'){out.append(slash*2+1,L'\\');out+=c;}else{out.append(slash,L'\\');out+=c;}slash=0;}out.append(slash*2,L'\\');return out+L"\"";}
inline PROCESS_INFORMATION updateProcess(const fs::path& application,const std::wstring& arguments){STARTUPINFOW startup{sizeof startup};PROCESS_INFORMATION process{};auto line=updateQuote(application.wstring())+L" "+arguments;std::vector<wchar_t> buffer(line.begin(),line.end());buffer.push_back(0);if(!CreateProcessW(application.c_str(),buffer.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,application.parent_path().c_str(),&startup,&process))throw std::runtime_error("업데이트 도우미 실행 실패");return process;}
inline void launchUpdateHelper(const fs::path& root,bool rollback=false){auto helper=updatePath(root,L".updates/helper.exe"),target=updatePath(root,L"SNUWCANVAS.exe");fs::create_directories(helper.parent_path());fs::copy_file(target,helper,fs::copy_options::overwrite_existing);auto process=updateProcess(helper,(rollback?L"--rollback-update ":L"--apply-update ")+updateQuote(fs::weakly_canonical(root).wstring())+L" "+std::to_wstring(GetCurrentProcessId()));CloseHandle(process.hThread);CloseHandle(process.hProcess);}
inline bool startupUpdate(const fs::path& root,const json& cfg){
 std::string rolledBackVersion;auto pending=updatePath(root,L".updates/pending.json");if(fs::exists(pending)){auto journal=json::parse(readFile(pending));if(str(journal,"state")=="rolled_back")rolledBackVersion=str(journal,"version");if(str(journal,"state")=="awaiting_health"){if(flag(journal,"boot_started")){launchUpdateHelper(root,true);return true;}journal["boot_started"]=true;updateJournal(root,journal);}else if(str(journal,"state")=="prepared"&&fs::exists(updatePath(root,L".updates/backups/"+wide(str(journal,"old_sha256"))+L".exe"))){launchUpdateHelper(root,true);return true;}}
 if(!flag(cfg,"auto_update",true)||str(cfg,"api").empty())return false;NetworkScope scope(nullptr,std::chrono::steady_clock::now()+std::chrono::seconds(180));json envelope;try{envelope=request("GET",joinUrl(str(cfg,"api"),"/api/updates/manifest"),"","","application/json",nullptr,65536,15000).object();}catch(...){return false;}if(!flag(envelope,"enabled"))return false;auto release=verifiedRelease(envelope);if(compareVersion(str(release,"version"),CLIENT_VERSION)<=0)return false;bool required=compareVersion(CLIENT_VERSION,str(release,"min_client_version"))<0;if(str(release,"version")==rolledBackVersion){if(required)throw std::runtime_error("문제가 있는 업데이트를 복구했습니다. 운영자의 새 릴리스가 필요합니다.");return false;}auto message=wide(str(release,"version"))+L" 버전이 있습니다.\n"+wide(str(release,"notes"))+L"\n\n검증 후 설치하고 다시 시작할까요?";if(MessageBoxW(nullptr,message.c_str(),required?L"필수 업데이트":L"snuwcanvas 업데이트",MB_YESNO|MB_ICONINFORMATION)!=IDYES){if(required)throw std::runtime_error("필수 업데이트를 설치해야 서비스를 사용할 수 있습니다.");return false;}
 auto directory=updatePath(root,L".updates/staged");fs::create_directories(directory);uint64_t used=0;for(auto& entry:fs::recursive_directory_iterator(updatePath(root,L".updates")))if(entry.is_regular_file())used+=entry.file_size();if(used>512*1024*1024)throw std::runtime_error("업데이트 저장소 512MiB 상한 · 기존 백업을 확인하세요.");auto candidate=directory/(wide(str(release,"sha256"))+L".exe"),part=candidate;part+=L".part";try{std::ofstream output(part,std::ios::binary|std::ios::trunc);if(!output)throw std::runtime_error("업데이트 저장 실패");auto response=request("GET",joinUrl(str(cfg,"api"),str(release,"artifact_path")),"","","application/octet-stream",nullptr,release["size"].get<size_t>(),180000,[&](const std::string& chunk){output.write(chunk.data(),chunk.size());if(!output)throw std::runtime_error("업데이트 저장 실패");});output.close();if(response.code!=200)throw std::runtime_error("업데이트 다운로드 실패");validateCandidate(part,release);if(fs::exists(candidate))fs::remove(candidate);fs::rename(part,candidate);atomicWrite(updatePath(root,L".updates/manifest.json"),envelope.dump());launchUpdateHelper(root);return true;}catch(...){fs::remove(part);throw;}
}
inline void updateHealthy(const fs::path& root){auto path=updatePath(root,L".updates/pending.json");if(!fs::exists(path))return;auto journal=json::parse(readFile(path));if(str(journal,"state")=="awaiting_health"){journal["state"]="healthy";updateJournal(root,journal);}}
inline int updateHelper(const fs::path& root,DWORD parent,bool rollback){bool applied=false;try{if(parent){HANDLE process=OpenProcess(SYNCHRONIZE,FALSE,parent);if(process){auto result=WaitForSingleObject(process,120000);CloseHandle(process);if(result!=WAIT_OBJECT_0)throw std::runtime_error("이전 프로그램 종료 대기 시간 초과");}}if(rollback)rollbackUpdate(root);else replaceUpdate(root,json::parse(readFile(updatePath(root,L".updates/manifest.json"))));applied=!rollback;auto process=updateProcess(updatePath(root,L"SNUWCANVAS.exe"),L"");CloseHandle(process.hThread);if(!rollback){auto deadline=GetTickCount64()+120000;while(GetTickCount64()<deadline){auto journal=json::parse(readFile(updatePath(root,L".updates/pending.json")));if(str(journal,"state")=="healthy")break;if(WaitForSingleObject(process.hProcess,100)==WAIT_OBJECT_0){rollbackUpdate(root);auto old=updateProcess(updatePath(root,L"SNUWCANVAS.exe"),L"");CloseHandle(old.hThread);CloseHandle(old.hProcess);break;}}}CloseHandle(process.hProcess);return 0;}catch(const std::exception& error){if(applied&&!rollback){try{rollbackUpdate(root);auto restored=updateProcess(updatePath(root,L"SNUWCANVAS.exe"),L"");CloseHandle(restored.hThread);CloseHandle(restored.hProcess);}catch(...){}}try{atomicWrite(updatePath(root,L".updates/last-error.json"),json{{"error",error.what()}}.dump());}catch(...){}return 1;}}
inline int updateTest(const fs::path& folder,const fs::path& envelopeFile,const fs::path& publicFile,bool strict=false){try{auto envelope=json::parse(readFile(envelopeFile));auto publicHex=readFile(publicFile);auto release=verifiedRelease(envelope,publicHex);auto target=folder/L"SNUWCANVAS.exe";auto before=fileSha256(target);replaceUpdate(folder,envelope,publicHex,strict);if(fileSha256(target)!=str(release,"sha256"))throw std::runtime_error("replace regression");rollbackUpdate(folder);if(fileSha256(target)!=before)throw std::runtime_error("rollback regression");if(compareVersion("v2.0.0-alpha.2","v2.0.0-alpha.10")>=0||compareVersion("v2.0.0","v2.0.0-rc.1")<=0)throw std::runtime_error("version regression");atomicWrite(folder/L"update-test-result.json",json{{"ok",true},{"gui_opened",false},{"rollback",true}}.dump());return 0;}catch(const std::exception& error){atomicWrite(folder/L"update-test-result.json",json{{"ok",false},{"gui_opened",false},{"error",error.what()}}.dump());return 1;}}
